<?php
use App\Models\Permission;use App\Models\PublicPage;use App\Models\SupportTicket;use App\Models\SupportTicketCategory;use App\Models\User;use App\Services\PublicPages\PublicPageTransferService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Notification;use Illuminate\Support\Facades\Storage;
uses(RefreshDatabase::class);
function extendedPageAdmin():User{$u=User::factory()->create(['email_verified_at'=>now()]);foreach([['view_admin','View Admin'],['manage_public_pages','Manage Public Pages'],['publish_public_pages','Publish Public Pages']] as[$n,$l]){$p=Permission::firstOrCreate(['name'=>$n],['label'=>$l,'group_name'=>'Content','description'=>$l]);$u->permissions()->syncWithoutDetaching([$p->id]);}return $u;}
it('stores an edited header and faq items',function(){Storage::fake('public');$u=extendedPageAdmin();$this->actingAs($u)->post('/admin/public-pages',['title'=>'FAQ','slug'=>'faq-help','page_type'=>'faq','status'=>'draft','is_active'=>true,'sort_order'=>10,'header_image_original'=>UploadedFile::fake()->image('source.jpg',1800,900),'header_image_rendered'=>UploadedFile::fake()->image('header.jpg',1600,700),'header_image_alt'=>'Helpful scene','faq_items'=>[['question'=>'What is this?','answer'=>'A public FAQ.','is_active'=>true,'sort_order'=>10]]])->assertRedirect('/admin/public-pages');$p=PublicPage::where('slug','faq-help')->firstOrFail();expect($p->header_image_path)->not->toBeNull()->and($p->faqItems()->count())->toBe(1);});
it('submits a contact page into support',function(){Notification::fake();SupportTicketCategory::factory()->create(['slug'=>'general-question','is_active'=>true]);$p=PublicPage::factory()->published()->create(['slug'=>'contact-us','page_type'=>'contact']);$this->post('/contact-us/contact',['name'=>'Visitor','email'=>'visitor@example.com','subject'=>'Question','topic'=>'Licensing','message'=>'Please contact me.'])->assertSessionHasNoErrors();expect(SupportTicket::count())->toBe(1);});
it('round trips public pages and faqs through json',function(){PublicPage::factory()->published()->create(['slug'=>'about'])->faqItems()->create(['question'=>'Q','answer'=>'A','is_active'=>true,'sort_order'=>10]);$t=app(PublicPageTransferService::class);$json=$t->exportJson();PublicPage::query()->forceDelete();$s=$t->importJson($json);expect($s['created'])->toBe(1)->and(PublicPage::where('slug','about')->firstOrFail()->faqItems()->count())->toBe(1);});
